import{_ as s,a0 as i,w as d,s as l,ao as p,I as r,a1 as n,A as a,x as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const P=JSON.parse('{"title":"安卓編年史 | LCTT x X-CMD","titleTemplate":false,"description":"安卓編年史 | LCTT (The history of Android) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"安卓編年史 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"安卓編年史 | LCTT (The history of Android) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"The history of Android/16 - The history of Android","title":"安卓編年史","tag":"The history of Android","desc":""},"relativePath":"The history of Android/16 - The history of Android.md","filePath":"[post].md"}'),m={name:"The history of Android/16 - The history of Android.md"};function h(T,t,f,u,g,A){const e=i("Link");return d(),l("div",null,[t[16]||(t[16]=p('<h1 id="安卓編年史" tabindex="-1">安卓編年史 <a class="header-anchor" href="#安卓編年史" aria-label="Permalink to “安卓編年史”">​</a></h1><h3 id="安卓-3-0-蜂巢—平板和設計復興" tabindex="-1">安卓 3.0 蜂巢—平板和設計復興 <a class="header-anchor" href="#安卓-3-0-蜂巢—平板和設計復興" aria-label="Permalink to “安卓 3.0 蜂巢—平板和設計復興”">​</a></h3><p>儘管薑餅中做了許多改變，安卓仍然是移動世界裏的醜小鴨。相比於 iPhone，它的優雅程度和設計完全抬不起頭。另一方面來説，為數不多的能與 iOS 的美學智慧相當的操作系統之一是 Palm 的 WebOS。WebOS 有着優秀的整體設計，創新的功能，而且被寄予期望能夠從和 iPhone 的長期競爭中拯救公司。</p><p>儘管如此，一年之後，Palm 資金鍊斷裂。Palm 公司未曾看到 iPhone 的到來，到 WebOS 就緒的時候已經太晚了。2010 年 4 月，惠普花費 10 億美元收購了 Palm。儘管惠普收購了一個擁有優秀用户界面的產品，但界面的首席設計師，Matias Duarte，並沒有加入惠普公司。2010 年 5 月，就在惠普接手 Palm 之前，Duarte 加入了谷歌。惠普買下了麪包，但谷歌僱傭了它的烘培師。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/03/Motorola-XOOM-MZ604.jpg" alt="第一部蜂巢設備，摩托羅拉 Xoom 10英寸平板。"></p><p><em>第一部蜂巢設備，摩托羅拉 Xoom 10英寸平板。</em></p><p>在谷歌，Duarte 被任命為安卓用户體驗主管。這是第一次有人公開掌管安卓的外觀。儘管 Matias 在安卓 2.2 發佈時就來到了谷歌，第一個真正受他影響的安卓版本是 3.0 蜂巢（Honeycomb），它在 2011 年 2 月發佈。</p><p>按谷歌自己的説法，蜂巢是匆忙問世的。10 個月前，蘋果發佈了 iPad，讓平板變得更加現代，谷歌希望能夠儘快做出回應。蜂巢就是那個回應，一個運行在 10 英寸觸摸屏上的安卓版本。悲傷的是，將這個系統推向市場是如此優先的事項，以至於邊邊角角都被砍去了以節省時間。</p><p>新系統只用於平板——手機不能升級到蜂巢，這加大了谷歌讓系統運行在差異巨大的不同尺寸屏幕上的難度。但是，僅支持平板而不支持手機也使得蜂巢源碼沒有泄露。之前的安卓版本是開源的，這使得黑客社區能夠將其最新版本移植到所有的不同設備之上。谷歌不希望應用開發者在支持不完美的蜂巢手機移植版本時感到壓力，所以谷歌將源碼留在自己手中，並且嚴格控制能夠擁有蜂巢的設備。匆忙的開發還導致了軟件問題。在發佈時，蜂巢不是特別穩定，SD 卡不能工作，Adobe Flash——安卓最大的特色之一——還不被支持。</p>',9)),r("p",null,[n(e,{href:"http://arstechnica.com/gadgets/2011/03/ars-reviews-the-motorola-xoom/"},{default:a(()=>[...t[0]||(t[0]=[o("摩托羅拉 Xoom",-1)])]),_:1}),t[1]||(t[1]=o(" 是為數不多的擁有蜂巢的設備之一，它是這個新系統的旗艦產品。Xoom 是一個 10 英寸，16:9 的平板，擁有 1GB 內存和 1GHz Tegra 2 雙核處理器。儘管是由谷歌直接控制更新的新版安卓發佈設備，它並沒有被叫做“Nexus”。對此最可能的原因是谷歌對它沒有足夠的信心稱其為旗艦。",-1))]),t[17]||(t[17]=p('<p>儘管如此，蜂巢是安卓的一個里程碑。在一個體驗設計師的主管之下，整個安卓用户界面被重構，絕大多數奇怪的應用設計都得到改進。安卓的默認應用終於看起來像整體的一部分，不同的界面有着相似的佈局和主題。然而重新設計安卓會是一個跨越了多個版本的項目——蜂巢只是將安卓塑造成型的開始。這第一稿為未來版本的安卓將如何運作奠定了基礎，但它也用了過多的科幻主題，谷歌將花費接下來的數個版本來淡化它。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/homeskreen.png" alt="蜂巢和薑餅的主屏幕。"></p><p><em>蜂巢和薑餅的主屏幕。 [Ron Amadeo供圖]</em></p><p>薑餅只是在它的光子壁紙上試驗了科幻外觀，蜂巢整個系統的以電子為靈感的主題讓它充滿科幻意味。所有東西都是黑色的，如果你需要對比色，你可以從一些不同色調的藍色中挑選。所有藍色的東西還有“光暈”效果，讓整個系統看起來像是外星科技創造的。默認背景是個六邊形的全息方陣（一個蜂巢！明白了嗎？），看起來像是一艘飛船上的傳送陣的地板。</p><p>蜂巢最重要的變化是增加了系統欄。摩托羅拉 Xoom 除了電源和音量鍵之外沒有配備實體按鍵，所以蜂巢添加了一個大黑色底欄到屏幕底部，用於放置導航按鍵。這意味着默認安卓界面不再需要特別的實體按鍵。在這之前，安卓沒有實體的返回、菜單和 Home 鍵就不能正常工作。現在，軟件提供了所有必需的按鈕，任何帶有觸摸屏的設備都能夠運行安卓。</p><p>新軟件按鍵帶來的最大的好處是靈活性。新的應用指南表明應用不再必需實體菜單按鍵，需要用到的時候，蜂巢會自動檢測並添加四個按鈕到系統欄讓應用正常工作。另一個軟件按鍵的靈活屬性是它們可以改變設備的屏幕方向。除了電源和音量鍵之外，Xoom 的方向實際上不是那麼重要。從用户的角度來看，系統欄始終處於設備的“底部”。代價是系統欄明顯佔據了一些屏幕空間。為了在10英寸平板上節省空間，狀態欄被合併到了系統欄中。所有的常用狀態指示放在了右側——有電源、連接狀態、時間還有通知圖標。</p><p>主屏幕的整個佈局都改變了，用户界面部件放在了設備的四個角落。屏幕底部左側放置着之前討論過的導航按鍵，右側用於狀態指示和通知，頂部左側顯示的是文本搜索和語音搜索，右側有應用抽屜和添加小部件的按鈕。</p><p><img src="http://cdn.arstechnica.net/wp-content/uploads/2014/02/lockscreen-and-recent.png" alt="新鎖屏界面和最近應用界面。"></p><p><em>新鎖屏界面和最近應用界面。 [Ron Amadeo供圖]</em></p><p>（因為 Xoom 是一部 [較重] 的 10 英寸，16:9 平板設備，這意味着它主要是橫屏使用。雖然大部分應用還支持豎屏模式，但是到目前為止，由於我們的版式限制，我們大部分使用的是豎屏模式的截圖。請記住蜂巢的截圖來自於 10 英寸的平板，而薑餅的截圖來自 3.7 英寸的手機。二者所展現的信息密度是不能直接比較的。）</p><p>解鎖界面——從菜單按鈕到旋轉式撥號盤再到滑動解鎖——移除了解鎖步驟的任何精度要求，它採用了一個環狀解鎖盤。從中間向任意方向向外滑動就能解鎖設備。就像旋轉式解鎖，這種解鎖方式更加符合人體工程學，而不用強迫你的手指完美地遵循一條筆直的解鎖路徑。</p><p>第二張圖中略縮圖條帶是由新增的“最近應用”按鈕打開的界面，現在處在返回鍵和 Home 鍵旁邊。不像薑餅中長按 Home 鍵顯示一組最近應用的圖標，蜂巢在屏幕上顯示應用圖標和略縮圖，使得在任務間切換變得更加方便。“最近應用”的靈感明顯來自於 Duarte 在 WebOS 中的“卡片式”多任務管理，其使用全屏略縮圖來切換任務。這個設計提供和 WebOS 的任務切換一樣的易識別體驗，但更小的略縮圖允許更多的應用一次性顯示在屏幕上。</p><p>儘管最近應用的實現看起來和你現在的設備很像，這個版本實際上是非常早期的。這個列表不能滾動，這意味着豎屏下只能顯示七個應用，橫屏下只能顯示五個。任何超出範圍的應用會從列表中去除。而且你也不能通過滑動略縮圖來關閉應用——這只是個靜態的列表。</p><p>從這裏我們可以看到電子靈感影響的完整主題效果：略縮圖的周圍有藍色的輪廓以及神秘的光暈。這張截圖還展示軟件按鍵的好處——上下文。返回按鈕可以關閉略縮圖列表，所以這裏的箭頭指向下方，而不是通常的樣子。</p><hr><p><img src="https://cdn.arstechnica.net/wp-content/uploads/2016/05/r.amadeo-45843.jpg" alt="Ron Amadeo"></p>',16)),r("p",null,[n(e,{href:"http://arstechnica.com/author/ronamadeo"},{default:a(()=>[...t[2]||(t[2]=[o("Ron Amadeo",-1)])]),_:1}),t[3]||(t[3]=o(" / Ron是Ars Technica的評論編緝，專注於安卓系統和谷歌產品。他總是在追尋新鮮事物，還喜歡拆解事物看看它們到底是怎麼運作的。",-1))]),r("p",null,[n(e,{href:"https://twitter.com/RonAmadeo"},{default:a(()=>[...t[4]||(t[4]=[o("@RonAmadeo",-1)])]),_:1})]),t[18]||(t[18]=r("hr",null,null,-1)),r("p",null,[t[6]||(t[6]=o("via: ",-1)),n(e,{href:"http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/16/"},{default:a(()=>[...t[5]||(t[5]=[o("http://arstechnica.com/gadgets/2016/10/building-android-a-40000-word-history-of-googles-mobile-os/16/",-1)])]),_:1})]),r("p",null,[t[9]||(t[9]=o("譯者：",-1)),n(e,{href:"https://github.com/alim0x"},{default:a(()=>[...t[7]||(t[7]=[o("alim0x",-1)])]),_:1}),t[10]||(t[10]=o(" 校對：",-1)),n(e,{href:"https://github.com/Bestony"},{default:a(()=>[...t[8]||(t[8]=[o("Bestony",-1)])]),_:1})]),r("p",null,[t[13]||(t[13]=o("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[11]||(t[11]=[o("LCTT",-1)])]),_:1}),t[14]||(t[14]=o(" 原創翻譯，",-1)),n(e,{href:"http://linux.cn/"},{default:a(()=>[...t[12]||(t[12]=[o("Linux中國",-1)])]),_:1}),t[15]||(t[15]=o(" 榮譽推出",-1))])])}const x=s(m,[["render",h]]);export{P as __pageData,x as default};
